package vn.covie.inventory.application;
import java.time.Instant; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.catalog.model.*; import vn.covie.inventory.model.InventoryBalanceEntity; import vn.covie.inventory.persistence.InventoryBalanceRepository; import vn.covie.shared.id.UuidV7Generator;
@Service public class InventoryModeCoordinator { private final InventoryBalanceRepository balances; private final UuidV7Generator ids; public InventoryModeCoordinator(InventoryBalanceRepository balances,UuidV7Generator ids){this.balances=balances;this.ids=ids;} @Transactional public void onOfferCreated(LocationVariantEntity offer,CatalogItemType type){if(type==CatalogItemType.PRODUCT&&offer.getInventoryMode()==InventoryMode.TRACKED)balances.findById(offer.getId()).orElseGet(()->balances.save(InventoryBalanceEntity.zero(offer.getId(),Instant.now())));} @Transactional public void beforeInventoryModeChange(LocationVariantEntity offer,InventoryMode oldMode,InventoryMode newMode,CatalogItemType type){if(type!=CatalogItemType.PRODUCT||oldMode==newMode)return;if(newMode==InventoryMode.TRACKED){balances.findById(offer.getId()).orElseGet(()->balances.save(InventoryBalanceEntity.zero(offer.getId(),Instant.now())));return;}if(oldMode==InventoryMode.TRACKED){InventoryBalanceEntity b=balances.findById(offer.getId()).orElseThrow();if(b.getReservedQuantity()!=0||b.getStockOnHand()!=0)throw new IllegalStateException("Tracked inventory must be zero before disabling tracking");balances.delete(b);}} }
